DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_engineer INT;
BEGIN
  FOR rec IN SELECT * FROM alert_events ORDER BY event_id LOOP
    SELECT status, assigned_engineer_id INTO cur_status, cur_engineer FROM alerts WHERE alert_id = rec.alert_id;

    IF rec.event_type = 1 AND cur_status = 'open' THEN
      UPDATE alerts SET status = 'acknowledged', assigned_engineer_id = rec.engineer_id, ack_timestamp = rec.event_timestamp WHERE alert_id = rec.alert_id;
    ELSIF rec.event_type = 2 AND cur_status = 'acknowledged' AND rec.engineer_id = cur_engineer THEN
      UPDATE alerts SET status = 'escalated', ack_timestamp = NULL WHERE alert_id = rec.alert_id;
    ELSIF rec.event_type = 3 AND (cur_status = 'escalated' OR (cur_status = 'acknowledged' AND rec.engineer_id = cur_engineer)) THEN
      UPDATE alerts SET status = 'resolved' WHERE alert_id = rec.alert_id;
    END IF;
  END LOOP;
END $$;
SELECT * FROM alerts ORDER BY alert_id;
